struct TrieNode {
    unordered_map<char, TrieNode*> children;
    bool is_end = false;
};
class Solution {
public:
    string longestCommonPrefix(vector<string>& strs) {
        if (strs.empty()) return "";
        TrieNode* root = new TrieNode();
        for (auto &s : strs) {
            if (s.empty()) return "";
            TrieNode* node = root;
            for (char ch : s) {
                if (!node->children.count(ch)) node->children[ch] = new TrieNode();
                node = node->children[ch];
            }
            node->is_end = true;
        }
        string prefix;
        TrieNode* node = root;
        while (!node->is_end && node->children.size() == 1) {
            auto it = node->children.begin();
            prefix.push_back(it->first);
            node = it->second;
        }
        return prefix;
    }
};

