from typing import List
class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False
class Solution:
    def longestCommonPrefix(self, strs: List[str]) -> str:
        if not strs:
            return ''
        root = TrieNode()
        for s in strs:
            if s == '':
                return ''
            node = root
            for ch in s:
                if ch not in node.children:
                    node.children[ch] = TrieNode()
                node = node.children[ch]
            node.is_end = True
        prefix = []
        node = root
        while True:
            if node.is_end:
                break
            if len(node.children) != 1:
                break
            ch, nxt = next(iter(node.children.items()))
            prefix.append(ch)
            node = nxt
        return ''.join(prefix)

